    tools: tools);

// Map the AG-UI agent endpoint
app.MapAGUI("/", agent);

await app.RunAsync();","link":"https://learn.microsoft.com/en-us/agent-framework/integrations/ag-ui/backend-tool-rendering?pivots=programming-language-csharp#creating-an-ag-ui-server-with-function-tools","language":"csharp"},{"description":"description: Defines the AG-UI server application using ASP.NET Core, setting up dependency injection, configuring the Azure OpenAI client, creating an AI agent, mapping the AG-UI endpoint, and running the server asynchronously.
